    const second={...input,loginId:'race_second',name:'다른 가상 근로자'};assert.equal((await send(b,'/api/join','POST',second)).status,201);const secondWorker=(await (await send(b,`/api/workers?siteId=${site.id}`,'GET',undefined,admin)).json()).find(row=>row.name===second.name),siteKey=(await (await send(b,`/api/join?token=${token}`)).json()).siteKey,waiting=once(children[0].stdout,'data'),revokedLogin=send(a,'/api/worker/login','POST',{token,loginId:second.loginId,password:second.password});revokedLogin.catch(()=>{});assert.match(String((await waiting)[0]),/LOGIN_HASH/);assert.equal((await send(b,`/api/sites/${site.id}/invitation`,'DELETE',undefined,admin)).status,200);assert.equal((await revokedLogin).status,401);const afterRevoke=new DatabaseSync(join(dir,'jweb.sqlite'));try{assert.equal(afterRevoke.prepare('SELECT count(*) AS n FROM attendance WHERE worker_id=?').get(secondWorker.id).n,0);assert.equal(afterRevoke.prepare('SELECT count(*) AS n FROM worker_sessions WHERE worker_id=?').get(secondWorker.id).n,0);}finally{afterRevoke.close();}assert.equal((await send(b,'/api/worker/login','POST',{siteKey,loginId:second.loginId,password:second.password})).status,200);
